import { useContext } from 'react';
import { Link } from 'react-router-dom';
import { AuthContext } from '../context/AuthContext';

const UserInfoCard = () => {
  const { usuario } = useContext(AuthContext);

  if (!usuario) return null;

  const fechaRegistro = new Date(usuario.fechaRegistro);
  const fechaFormateada = fechaRegistro.toLocaleDateString('es-ES', {
    year: 'numeric',
    month: 'long',
    day: 'numeric'
  });

  return (
    <div className="p-4 rounded-4 mb-4" style={{
      background: 'linear-gradient(135deg, rgba(0, 255, 65, 0.1), rgba(97, 218, 251, 0.1))',
      backdropFilter: 'blur(10px)',
      border: '1px solid rgba(0, 255, 65, 0.3)',
      boxShadow: '0 8px 32px rgba(0, 0, 0, 0.3)'
    }}>
      <div className="d-flex align-items-center gap-3">
        {/* Avatar */}
        <div style={{
          width: '80px',
          height: '80px',
          borderRadius: '50%',
          background: 'linear-gradient(135deg, #00ff41, #39ff14)',
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'center',
          fontSize: '2.5rem',
          boxShadow: '0 8px 25px rgba(0, 255, 65, 0.4)',
          flexShrink: 0
        }}>
          🕷️
        </div>

        {/* Información */}
        <div className="flex-grow-1">
          <h4 className="mb-1 fw-bold" style={{ color: '#00ff41' }}>
            {usuario.nombre} {usuario.apellido}
          </h4>
          <p className="mb-1" style={{ color: '#61dafb', fontSize: '0.9rem' }}>
            @{usuario.usuario}
          </p>
          <p className="mb-0" style={{ color: '#a8dadc', fontSize: '0.85rem' }}>
            📧 {usuario.email}
          </p>
          <p className="mb-0 mt-1" style={{ color: '#6c757d', fontSize: '0.8rem' }}>
            Miembro desde {fechaFormateada}
          </p>
        </div>

        {/* Botón Editar */}
        <Link
          to="/editar-perfil"
          className="btn btn-sm fw-semibold"
          style={{
            background: 'rgba(97, 218, 251, 0.2)',
            border: '2px solid rgba(97, 218, 251, 0.4)',
            borderRadius: '10px',
            color: '#61dafb',
            padding: '8px 20px',
            textDecoration: 'none',
            whiteSpace: 'nowrap'
          }}
        >
          ✏️ Editar
        </Link>
      </div>
    </div>
  );
};

export default UserInfoCard;