import { useState, useContext } from 'react';
import { useNavigate, Link } from 'react-router-dom';
import { useForm } from 'react-hook-form';
import Swal from 'sweetalert2';
import RickMortyBackground from '../components/RickMortyBackground';
import Navbar from '../components/Navbar';
import { AuthContext } from '../context/AuthContext';

const EditarPerfil = () => {
  const { usuario, actualizarPerfil } = useContext(AuthContext);
  const navigate = useNavigate();
  const { register, handleSubmit, formState: { errors }, watch } = useForm({
    defaultValues: {
      nombre: usuario?.nombre || '',
      apellido: usuario?.apellido || '',
      email: usuario?.email || '',
      usuario: usuario?.usuario || ''
    }
  });
  
  const [mostrarPasswordActual, setMostrarPasswordActual] = useState(false);
  const [mostrarPasswordNueva, setMostrarPasswordNueva] = useState(false);
  const [cambiarPassword, setCambiarPassword] = useState(false);
  const [cargando, setCargando] = useState(false);

  const validaciones = {
    nombre: {
      required: "El nombre es obligatorio",
      pattern: {
        value: /^[a-zA-ZáéíóúÁÉÍÓÚñÑ\s]+$/,
        message: "El nombre solo puede contener letras"
      },
      minLength: {
        value: 2,
        message: "El nombre debe tener al menos 2 caracteres"
      }
    },
    apellido: {
      required: "El apellido es obligatorio",
      pattern: {
        value: /^[a-zA-ZáéíóúÁÉÍÓÚñÑ\s]+$/,
        message: "El apellido solo puede contener letras"
      },
      minLength: {
        value: 2,
        message: "El apellido debe tener al menos 2 caracteres"
      }
    },
    email: {
      required: "El correo electrónico es obligatorio",
      pattern: {
        value: /^[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}$/i,
        message: "Correo electrónico inválido"
      }
    },
    usuario: {
      required: "El nombre de usuario es obligatorio",
      pattern: {
        value: /^[a-zA-Z0-9_]+$/,
        message: "Solo letras, números y guiones bajos"
      },
      minLength: {
        value: 4,
        message: "Mínimo 4 caracteres"
      },
      maxLength: {
        value: 20,
        message: "Máximo 20 caracteres"
      }
    },
    passwordActual: cambiarPassword ? {
      required: "La contraseña actual es obligatoria",
      minLength: {
        value: 6,
        message: "Mínimo 6 caracteres"
      }
    } : {},
    passwordNueva: cambiarPassword ? {
      required: "La nueva contraseña es obligatoria",
      minLength: {
        value: 6,
        message: "Mínimo 6 caracteres"
      },
      pattern: {
        value: /^(?=.*[a-z])(?=.*[A-Z])(?=.*\d)/,
        message: "Debe contener mayúscula, minúscula y número"
      }
    } : {},
    confirmarPasswordNueva: cambiarPassword ? {
      required: "Confirma la nueva contraseña",
      validate: (value) => value === watch('passwordNueva') || "Las contraseñas no coinciden"
    } : {}
  };

  const onSubmit = async (data) => {
    setCargando(true);

    const resultado = actualizarPerfil({
      ...data,
      cambiarPassword,
      passwordActual: cambiarPassword ? data.passwordActual : null,
      passwordNueva: cambiarPassword ? data.passwordNueva : null
    });

    setCargando(false);

    if (resultado.success) {
      await Swal.fire({
        icon: 'success',
        title: '¡Perfil Actualizado!',
        text: 'Tus datos han sido actualizados exitosamente',
        background: '#1a0933',
        color: '#fff',
        confirmButtonColor: '#00ff41',
        timer: 2000
      });
      navigate('/');
    } else {
      Swal.fire({
        icon: 'error',
        title: 'Error',
        text: resultado.message,
        background: '#1a0933',
        color: '#fff',
        confirmButtonColor: '#ff0000'
      });
    }
  };

  return (
    <>
      <RickMortyBackground />
      <Navbar />
      
      <div className="container-fluid min-vh-100 d-flex align-items-center justify-content-center py-5">
        <div className="row justify-content-center w-100">
          <div className="col-11 col-sm-10 col-md-8 col-lg-6 col-xl-5">
            
            <div className="text-center mb-4">
              <h1 className="display-5 fw-bold mb-2" style={{
                color: '#00ff41',
                textShadow: '0 0 20px rgba(0, 255, 65, 0.6)'
              }}>
                ✏️ Editar Perfil
              </h1>
              <p style={{ color: '#a8dadc' }}>Actualiza tu información personal</p>
            </div>

            <div className="p-4 p-sm-5 rounded-4" style={{
              background: 'rgba(255, 255, 255, 0.05)',
              backdropFilter: 'blur(15px)',
              border: '1px solid rgba(255, 255, 255, 0.1)',
              boxShadow: '0 15px 50px rgba(0, 0, 0, 0.5)'
            }}>
              
              <form onSubmit={handleSubmit(onSubmit)}>
                
                {/* Avatar/Foto de perfil */}
                <div className="text-center mb-4">
                  <div style={{
                    width: '120px',
                    height: '120px',
                    borderRadius: '50%',
                    background: 'linear-gradient(135deg, #00ff41, #39ff14)',
                    margin: '0 auto',
                    display: 'flex',
                    alignItems: 'center',
                    justifyContent: 'center',
                    fontSize: '3rem',
                    boxShadow: '0 8px 25px rgba(0, 255, 65, 0.4)'
                  }}>
                    🕷️
                  </div>
                  <p className="mt-2" style={{ color: '#61dafb', fontSize: '0.9rem' }}>
                    {usuario?.nombre} {usuario?.apellido}
                  </p>
                </div>

                {/* Información Personal */}
                <h5 className="mb-3 fw-bold" style={{ color: '#61dafb' }}>
                  📋 Información Personal
                </h5>

                <div className="row g-3">
                  {/* Nombre */}
                  <div className="col-md-6">
                    <label htmlFor="nombre" className="form-label fw-semibold" style={{ color: '#61dafb', fontSize: '0.9rem' }}>
                      Nombre
                    </label>
                    <input
                      type="text"
                      className={`form-control ${errors.nombre ? 'is-invalid' : ''}`}
                      id="nombre"
                      {...register('nombre', validaciones.nombre)}
                      style={{
                        background: 'rgba(255, 255, 255, 0.1)',
                        border: `2px solid ${errors.nombre ? '#dc3545' : 'rgba(97, 218, 251, 0.3)'}`,
                        color: 'white',
                        borderRadius: '12px',
                        padding: '12px 16px'
                      }}
                    />
                    {errors.nombre && (
                      <small className="text-danger d-block mt-1">{errors.nombre.message}</small>
                    )}
                  </div>

                  {/* Apellido */}
                  <div className="col-md-6">
                    <label htmlFor="apellido" className="form-label fw-semibold" style={{ color: '#61dafb', fontSize: '0.9rem' }}>
                      Apellido
                    </label>
                    <input
                      type="text"
                      className={`form-control ${errors.apellido ? 'is-invalid' : ''}`}
                      id="apellido"
                      {...register('apellido', validaciones.apellido)}
                      style={{
                        background: 'rgba(255, 255, 255, 0.1)',
                        border: `2px solid ${errors.apellido ? '#dc3545' : 'rgba(97, 218, 251, 0.3)'}`,
                        color: 'white',
                        borderRadius: '12px',
                        padding: '12px 16px'
                      }}
                    />
                    {errors.apellido && (
                      <small className="text-danger d-block mt-1">{errors.apellido.message}</small>
                    )}
                  </div>
                </div>

                {/* Email */}
                <div className="mt-3">
                  <label htmlFor="email" className="form-label fw-semibold" style={{ color: '#61dafb', fontSize: '0.9rem' }}>
                    Correo Electrónico
                  </label>
                  <input
                    type="email"
                    className={`form-control ${errors.email ? 'is-invalid' : ''}`}
                    id="email"
                    {...register('email', validaciones.email)}
                    style={{
                      background: 'rgba(255, 255, 255, 0.1)',
                      border: `2px solid ${errors.email ? '#dc3545' : 'rgba(97, 218, 251, 0.3)'}`,
                      color: 'white',
                      borderRadius: '12px',
                      padding: '12px 16px'
                    }}
                  />
                  {errors.email && (
                    <small className="text-danger d-block mt-1">{errors.email.message}</small>
                  )}
                </div>

                {/* Usuario */}
                <div className="mt-3">
                  <label htmlFor="usuario" className="form-label fw-semibold" style={{ color: '#61dafb', fontSize: '0.9rem' }}>
                    Nombre de Usuario
                  </label>
                  <input
                    type="text"
                    className={`form-control ${errors.usuario ? 'is-invalid' : ''}`}
                    id="usuario"
                    {...register('usuario', validaciones.usuario)}
                    style={{
                      background: 'rgba(255, 255, 255, 0.1)',
                      border: `2px solid ${errors.usuario ? '#dc3545' : 'rgba(97, 218, 251, 0.3)'}`,
                      color: 'white',
                      borderRadius: '12px',
                      padding: '12px 16px'
                    }}
                  />
                  {errors.usuario && (
                    <small className="text-danger d-block mt-1">{errors.usuario.message}</small>
                  )}
                </div>

                <hr style={{ borderColor: 'rgba(255, 255, 255, 0.1)', margin: '30px 0' }} />

                {/* Cambiar Contraseña */}
                <div className="mb-3">
                  <div className="form-check">
                    <input
                      className="form-check-input"
                      type="checkbox"
                      id="cambiarPassword"
                      checked={cambiarPassword}
                      onChange={(e) => setCambiarPassword(e.target.checked)}
                      style={{ cursor: 'pointer' }}
                    />
                    <label className="form-check-label fw-bold" htmlFor="cambiarPassword" style={{ color: '#61dafb', cursor: 'pointer' }}>
                      🔒 Cambiar Contraseña
                    </label>
                  </div>
                </div>

                {cambiarPassword && (
                  <div className="p-3 rounded-3 mb-3" style={{
                    background: 'rgba(97, 218, 251, 0.1)',
                    border: '1px solid rgba(97, 218, 251, 0.3)'
                  }}>
                    {/* Contraseña Actual */}
                    <div className="mb-3">
                      <label htmlFor="passwordActual" className="form-label fw-semibold" style={{ color: '#61dafb', fontSize: '0.9rem' }}>
                        Contraseña Actual
                      </label>
                      <div className="position-relative">
                        <input
                          type={mostrarPasswordActual ? "text" : "password"}
                          className={`form-control ${errors.passwordActual ? 'is-invalid' : ''}`}
                          id="passwordActual"
                          placeholder="••••••••"
                          {...register('passwordActual', validaciones.passwordActual)}
                          style={{
                            background: 'rgba(255, 255, 255, 0.1)',
                            border: `2px solid ${errors.passwordActual ? '#dc3545' : 'rgba(97, 218, 251, 0.3)'}`,
                            color: 'white',
                            borderRadius: '12px',
                            padding: '12px 16px',
                            paddingRight: '45px'
                          }}
                        />
                        <button
                          type="button"
                          onClick={() => setMostrarPasswordActual(!mostrarPasswordActual)}
                          style={{
                            position: 'absolute',
                            right: '10px',
                            top: '50%',
                            transform: 'translateY(-50%)',
                            background: 'none',
                            border: 'none',
                            color: '#61dafb',
                            cursor: 'pointer',
                            fontSize: '1.2rem'
                          }}
                        >
                          {mostrarPasswordActual ? '👁️' : '👁️‍🗨️'}
                        </button>
                      </div>
                      {errors.passwordActual && (
                        <small className="text-danger d-block mt-1">{errors.passwordActual.message}</small>
                      )}
                    </div>

                    {/* Nueva Contraseña */}
                    <div className="mb-3">
                      <label htmlFor="passwordNueva" className="form-label fw-semibold" style={{ color: '#61dafb', fontSize: '0.9rem' }}>
                        Nueva Contraseña
                      </label>
                      <div className="position-relative">
                        <input
                          type={mostrarPasswordNueva ? "text" : "password"}
                          className={`form-control ${errors.passwordNueva ? 'is-invalid' : ''}`}
                          id="passwordNueva"
                          placeholder="••••••••"
                          {...register('passwordNueva', validaciones.passwordNueva)}
                          style={{
                            background: 'rgba(255, 255, 255, 0.1)',
                            border: `2px solid ${errors.passwordNueva ? '#dc3545' : 'rgba(97, 218, 251, 0.3)'}`,
                            color: 'white',
                            borderRadius: '12px',
                            padding: '12px 16px',
                            paddingRight: '45px'
                          }}
                        />
                        <button
                          type="button"
                          onClick={() => setMostrarPasswordNueva(!mostrarPasswordNueva)}
                          style={{
                            position: 'absolute',
                            right: '10px',
                            top: '50%',
                            transform: 'translateY(-50%)',
                            background: 'none',
                            border: 'none',
                            color: '#61dafb',
                            cursor: 'pointer',
                            fontSize: '1.2rem'
                          }}
                        >
                          {mostrarPasswordNueva ? '👁️' : '👁️‍🗨️'}
                        </button>
                      </div>
                      {errors.passwordNueva && (
                        <small className="text-danger d-block mt-1">{errors.passwordNueva.message}</small>
                      )}
                    </div>

                    {/* Confirmar Nueva Contraseña */}
                    <div className="mb-0">
                      <label htmlFor="confirmarPasswordNueva" className="form-label fw-semibold" style={{ color: '#61dafb', fontSize: '0.9rem' }}>
                        Confirmar Nueva Contraseña
                      </label>
                      <input
                        type={mostrarPasswordNueva ? "text" : "password"}
                        className={`form-control ${errors.confirmarPasswordNueva ? 'is-invalid' : ''}`}
                        id="confirmarPasswordNueva"
                        placeholder="••••••••"
                        {...register('confirmarPasswordNueva', validaciones.confirmarPasswordNueva)}
                        style={{
                          background: 'rgba(255, 255, 255, 0.1)',
                          border: `2px solid ${errors.confirmarPasswordNueva ? '#dc3545' : 'rgba(97, 218, 251, 0.3)'}`,
                          color: 'white',
                          borderRadius: '12px',
                          padding: '12px 16px'
                        }}
                      />
                      {errors.confirmarPasswordNueva && (
                        <small className="text-danger d-block mt-1">{errors.confirmarPasswordNueva.message}</small>
                      )}
                    </div>
                  </div>
                )}

                {/* Botones */}
                <div className="d-flex gap-2 mt-4">
                  <button
                    type="submit"
                    disabled={cargando}
                    className="btn btn-lg w-100 fw-bold"
                    style={{
                      background: cargando ? 'rgba(0, 255, 65, 0.5)' : 'linear-gradient(135deg, #00ff41, #39ff14)',
                      border: 'none',
                      borderRadius: '12px',
                      color: '#000',
                      padding: '14px',
                      boxShadow: '0 8px 25px rgba(0, 255, 65, 0.4)',
                      cursor: cargando ? 'not-allowed' : 'pointer'
                    }}
                  >
                    {cargando ? '💾 Guardando...' : '💾 Guardar Cambios'}
                  </button>

                  <Link
                    to="/"
                    className="btn btn-lg fw-bold"
                    style={{
                      background: 'rgba(255, 255, 255, 0.1)',
                      border: '2px solid rgba(255, 255, 255, 0.2)',
                      borderRadius: '12px',
                      color: 'white',
                      padding: '14px 30px',
                      textDecoration: 'none',
                      display: 'flex',
                      alignItems: 'center',
                      justifyContent: 'center'
                    }}
                  >
                    ❌
                  </Link>
                </div>
              </form>

            </div>

            <div className="text-center mt-4">
              <Link to="/" style={{ color: '#61dafb', textDecoration: 'none' }}>
                ← Volver al inicio
              </Link>
            </div>

          </div>
        </div>
      </div>
    </>
  );
};

export default EditarPerfil;